els,P=read('build/opt1.xyz')
n=len(els)
# bonded pairs from distance
import itertools
bonds=set()
for i,j in itertools.combinations(range(n),2):
    d=np.linalg.norm(P[i]-P[j])
    e={els[i],els[j]}
    cut = 1.75 if 'H' not in e else 1.25
    if e=={'H','H'}: cut=0.9
    if d<cut: bonds.add((i,j))
close=[]
for i,j in itertools.combinations(range(n),2):
    if (i,j) in bonds: continue
    d=np.linalg.norm(P[i]-P[j])
    if d<1.8: close.append((i,els[i],j,els[j],round(d,2)))
print('nonbonded <1.8A:', close)
